command:
// ==========================================
// LUNAS WIRKUNG: BLITZSCHLAG (RONDRA)
//
// - aktive Meisterklinge wird beim Wirken geprüft
// - Dauer: QS × 4 Kampfrunden
// - Effektanlage über Block 5
// - Wirkungsende über Block 6
// - Angriffswächter über Block 18
// - nur gespeicherte Meisterklinge löst aus
// - Schaden: erkannter Schaden + QS TP
// - Effekt endet erst nach Schadensanwendung
// - eine Karte + roter GM-Button über Block 19.8
// ==========================================

(async function () {
const macroUuid = this?.uuid || null;

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt = !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register || !globalThis.DSK?.Schaden?.GMKarte || !globalThis.DSK?.Schaden?.IstAktiverGM || !globalThis.DSK?.Schaden?.FindeActor || !globalThis.DSK?.Schaden?.Angriffswaechter?.Register || !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde || !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden || !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen || !globalThis.DSK?.GabenUI?.GMMakroButton || !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen || !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute(); await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (!DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register || !DSK_FW?.Schaden?.GMKarte || !DSK_FW?.Schaden?.IstAktiverGM || !DSK_FW?.Schaden?.FindeActor || !DSK_FW?.Schaden?.Angriffswaechter?.Register || !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde || !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden || !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen || !DSK_FW?.GabenUI?.GMMakroButton || !DSK_FW?.GabenUI?.AnfrageKarteErstellen || !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework inklusive Block 18 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

const gabenName = "Blitzschlag", vollerName = "Blitzschlag (Rondra)", ahne = "Rondra";
const reaktionsKey = "blitzschlagrondra", flagKey = "pendingBlitzschlagRondra";
const endeText = "Die knisternden, geisterhaften Blitze auf der Klinge erlöschen. Rondras Zorn schwindet.";
DSK_FW.EffektEnde.Register(reaktionsKey, vollerName, endeText);

// +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
};

const findeMeisterklinge = actor => (actor?.effects || []).find(e =>
    !e.disabled && String(e.name || e.label || "").toLowerCase().includes("meisterklinge")
) || null;

const klingenNameAus = effect => {
    let name = String(effect?.name || effect?.label || "Meisterklinge").trim();
    if (name.includes("-")) name = name.split("-").slice(1).join("-").trim();
    return name || "Meisterklinge";
};

const findeAlteEffekte = (actor, casterUuid) => (actor?.effects || []).filter(e =>
    (e.name || e.label || "") === vollerName &&
    e.getFlag("dsk", "isBlitzschlag") === true &&
    e.getFlag("dsk", "casterUuid") === casterUuid
);

const beschreibungFuer = (klingenName, qs) =>
    `Das Rondrakind lädt seine <b>${klingenName}</b> mit der Kraft Rondras auf.` +
    `<br><br>Der nächste erfolgreiche Angriff muss zwingend mit <b>${klingenName}</b> erfolgen, um den Blitzschlag zu entladen.` +
    `<br><br>Der verursachte Schaden wird um <b>+${qs} TP</b> erhöht.` +
    `<br><br><b>Voraussetzung:</b> Aktive Meisterklinge (${klingenName})` +
    `<br><br><b>Zielkategorie:</b> Sich selbst`;

// +++ 4 - REAKTIONSWÄCHTER ÜBER BLOCK 18 ++++++++++++++++++

const registriereReaktion = ({ actor, effect }) => {
    if (!actor || !effect) return null;
    const klingenName = effect.getFlag("dsk", "klingenName");
    if (!klingenName) return null;

    return DSK_FW.Schaden.Angriffswaechter.Register({
        key: `${reaktionsKey}-${actor.uuid}`, actor,
        effektId: effect.id, effektUuid: effect.uuid,
        erlaubteWaffen: [klingenName], rolle: "angreifer",
        einmalig: true, protokollieren: true,

        beiErfolg: async ({ actor, effekt, message, angriff, waffenName }) => {
            if (!DSK_FW.Schaden.IstAktiverGM() || !actor || !effekt || !message || !angriff || angriff.schaden <= 0) return false;

            const gespeicherteKlinge = String(effekt.getFlag("dsk", "klingenName") || "");
            if (!DSK_FW.Schaden.Angriffswaechter._WaffePasst(waffenName, [gespeicherteKlinge])) return false;

            const zielDaten = DSK_FW.Schaden.FindeActor(angriff.verteidigerName, actor.id);
            if (!zielDaten?.actor) {
                ui.notifications.warn(`Luna sagt 🌙: Das Ziel „${angriff.verteidigerName}“ konnte nicht automatisch erkannt werden.`);
                return false;
            }

            const zielActor = zielDaten.actor;
            if (zielActor.id === actor.id || zielActor.uuid === actor.uuid) return false;

            const zielName = zielDaten.token?.name || zielDaten.name || DSK_FW.ResolveTokenName(zielActor);
            const casterName = DSK_FW.ResolveTokenName(actor);
            const basisTP = Math.max(0, Math.floor(Number(angriff.schaden) || 0));
            const bonusTP = Math.max(1, Math.floor(Number(effekt.getFlag("dsk", "bonus")) || 1));
            if (basisTP <= 0) return false;

            const schadensKarte = await DSK_FW.Schaden.GMKarte({
                key: `${reaktionsKey}-${effekt.id}-${message.id}`,
                titel: "Blitzschlag – Entladung", ahne,
                zusammenfassung: `Getroffen: ${zielName}`,
                beschreibung: `<b>${casterName}</b> hat <b>${zielName}</b> erfolgreich mit <b>${waffenName}</b> angegriffen.` +
                    `<br><br>Die aufgeladene Meisterklinge entlädt Rondras Zorn. Der erkannte Schaden wird um <b>+${bonusTP} TP</b> erhöht.`,
                modus: "addition", basis: basisTP, bonus: bonusTP,
                ziele: [{ uuid: zielActor.uuid, name: zielName }],
                buttonText: "Gesamtschaden anwenden",
                bestaetigungsTitel: "Blitzschlag – Schaden angewendet",
                effektUuid: effekt.uuid, effektVerbrauchen: true,
                quelleUuid: actor.uuid,
                abschlussText: "...und Rondras Segen endet.",
                vollTrefferText: "...und Rondras Segen endet.",
                lepDetailsVerbergen: true
            });

            return Boolean(schadensKarte);
        }
    });
};

// +++ 5 - BLITZSCHLAG AUF GM-CLIENT ANLEGEN +++++++++++++++

const wendeBlitzschlagAn = async ({ casterActor, casterName, qs, klingenName }) => {
    if (!casterActor || !DSK_FW.Schaden.IstAktiverGM()) return false;

    // Meisterklinge beim Verarbeiten erneut kontrollieren.
    const meisterklinge = findeMeisterklinge(casterActor);
    if (!meisterklinge) return false;

    const aktuelleKlinge = klingenNameAus(meisterklinge);
    if (DSK_FW.Schaden.NormalisiereName(aktuelleKlinge) !== DSK_FW.Schaden.NormalisiereName(klingenName)) {
        ui.notifications.warn(`Luna sagt 🌙: Die aktive Meisterklinge von ${casterName} stimmt nicht mehr mit ${klingenName} überein.`);
        return false;
    }

    const dauerRunden = qs * 4, dauerText = `${dauerRunden} Kampfrunde(n) (${qs} QS × 4 KR)`;
    const beschreibung = beschreibungFuer(klingenName, qs);

    const alteEffekte = findeAlteEffekte(casterActor, casterActor.uuid);
    if (alteEffekte.length) await casterActor.deleteEmbeddedDocuments("ActiveEffect", alteEffekte.map(e => e.id));

    let blitzEffect = null;
    try {
        blitzEffect = await DSK_FW.Effekt.Anwenden({
            name: vollerName, ahne,
            beschreibung: `${beschreibung}<br><br><b>Wirkungsdauer:</b> ${dauerText}`,
            gabeZiel: "", qs, ziel: casterActor,
            duration: { rounds: dauerRunden, startTime: game.time.worldTime },
            showIcon: 1, statuses: ["blitzschlag"],
            flags: { dsk: {
                isBlitzschlag: true, casterUuid: casterActor.uuid, casterName, qs,
                klingenName, erlaubteWaffen: [klingenName], bonus: qs,
                schadensReaktion: reaktionsKey, modus: "addition", rolle: "angreifer",
                einmalig: true, effektVerbrauchen: true,
                wirkungsende: { sfName: reaktionsKey, basisEffektName: vollerName, beschreibungFuerEnde: endeText }
            }}
        });

        if (!blitzEffect) throw new Error("Block 5 hat keinen Blitzschlag-Effekt zurückgegeben.");

        const endeDaten = blitzEffect.getFlag("dsk", "wirkungsende");
        const effektErfolgreich =
            (blitzEffect.name || blitzEffect.label || "") === vollerName &&
            blitzEffect.getFlag("dsk", "isBlitzschlag") === true &&
            blitzEffect.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            Number(blitzEffect.getFlag("dsk", "qs")) === qs &&
            blitzEffect.getFlag("dsk", "klingenName") === klingenName &&
            Number(blitzEffect.getFlag("dsk", "bonus")) === qs &&
            blitzEffect.getFlag("dsk", "schadensReaktion") === reaktionsKey &&
            blitzEffect.getFlag("dsk", "modus") === "addition" &&
            blitzEffect.getFlag("dsk", "rolle") === "angreifer" &&
            endeDaten?.sfName === reaktionsKey &&
            endeDaten?.basisEffektName === vollerName &&
            endeDaten?.beschreibungFuerEnde === endeText;

        if (!effektErfolgreich) throw new Error("Der Blitzschlag-Effekt wurde nicht vollständig angelegt.");

        const waechterKey = registriereReaktion({ actor: casterActor, effect: blitzEffect });
        if (!waechterKey) throw new Error("Der Blitzschlag-Wächter konnte nicht registriert werden.");

        return true;
    } catch (error) {
        console.error("Blitzschlag: Effektanlage/Wächterregistrierung fehlgeschlagen.", { casterActor: casterActor.name, klingenName, qs, error });
        if (blitzEffect) await blitzEffect.delete();
        return false;
    }
};

// +++ 6 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++

const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!casterActor || !daten || !DSK_FW.Schaden.IstAktiverGM()) return false;
    if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) return false;
    if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
        ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
        return false;
    }

    const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
    if (!casterToken) return false;

    const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
    const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
    const klingenName = String(daten.klingenName || "").trim();
    const erfolgreich = Boolean(klingenName && await wendeBlitzschlagAn({ casterActor, casterName, qs, klingenName }));

    await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
        messageId: daten.messageId, gabenName: vollerName, ahne,
        beschreibung: daten.beschreibung || "", wirkender: casterName,
        ziele: erfolgreich ? [{ name: casterName, rolle: `Waffe aufgeladen: ${klingenName}` }] : [],
        misserfolge: erfolgreich ? [] : [{ name: casterName, grund: "Meisterklinge, Effekt oder Schadensreaktion konnte nicht bestätigt werden" }],
        dauerText: `${qs * 4} Kampfrunde(n) (${qs} QS × 4 KR)`, erfolgreich
    });

    if (erfolgreich) ui.notifications.info(`Luna sagt 🌙: Blitzschlag ist auf ${klingenName} aktiv.`);
    else ui.notifications.error("Luna sagt 🌙: Blitzschlag konnte nicht vollständig aktiviert werden!");
    return true;
};

// +++ 7 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

if (game.user.isGM) {
    const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);
    if (anfragen.length) {
        for (const anfrageActor of anfragen) {
            const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
            if (!daten) continue;
            if (await verarbeiteAnfrage(anfrageActor, daten)) await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
        }
        return;
    }
}

// +++ 8 - WIRKENDER + QS + MEISTERKLINGE ++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;
if (!casterActor) casterActor =
    canvas.tokens.placeables.map(t => t.actor).find(a => a?.getFlag("world", "letzteGabenQS") !== undefined) ||
    game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined) || null;

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
if (!game.user.isGM && !casterActor.isOwner) return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!");

const casterName = DSK_FW.ResolveTokenName(casterActor);
const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor, gabenName,
    suchbegriffe: ["Blitzschlag Probe", "Blitzschlag"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0, protokollieren: true
});

if (qs <= 0) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn("Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!");
}

const meisterklinge = findeMeisterklinge(casterActor);
if (!meisterklinge) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: "Der Blitzschlag verfehlt seine Wirkung: Es wird keine aktive Meisterklinge geführt.",
        wirkender: casterName, ziele: [],
        misserfolge: [{ name: casterName, grund: "Keine aktive Meisterklinge" }],
        dauerText: "0 Kampfrunden", gmBereich: false,
        angewendet: true, erfolgreich: false, anfragenderUserId: game.user.id
    });
    await raeumeQSAuf(casterActor);
    return;
}

const klingenName = klingenNameAus(meisterklinge);
const dauerText = `${qs * 4} Kampfrunde(n) (${qs} QS × 4 KR)`;
const beschreibung = beschreibungFuer(klingenName, qs);

// +++ 9 - GEMEINSAME KARTE + GM-ANFRAGE +++++++++++++++++++

const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid, "Effekt anwenden",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
    ziele: [{ name: casterName, rolle: `Waffe aufladen: ${klingenName}` }],
    misserfolge: [], dauerText,
    gmLink, gmBereich: !game.user.isGM,
    anfragenderUserId: game.user.id
});

if (!nachricht) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
}

const anfrageDaten = {
    casterUuid: casterActor.uuid, casterName,
    casterTokenId: casterToken.id,
    casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
    qs, klingenName, beschreibung,
    sceneId: canvas.scene?.id || null,
    requestedByUserId: game.user.id,
    messageId: nachricht.id, macroUuid, erstellt: Date.now()
};

if (game.user.isGM) {
    await verarbeiteAnfrage(casterActor, anfrageDaten);
    await raeumeQSAuf(casterActor);
    return;
}

await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
await raeumeQSAuf(casterActor);
ui.notifications.info("Luna sagt 🌙: Blitzschlag wurde bei der Spielleitung zur Aktivierung beantragt.");

}).call(this);
